// Turns conversation JSON (/backend-api/conversation/{id}) into Markdown and HTML.
// Images are not downloaded here: each image receives a CGXIMG<n>Z marker,
// later replaced with a local path or remote URL (see content.js).
(() => {
  const ROLE_LABELS = { user: "User", assistant: "ChatGPT", thinking: "Thinking" };
  const PUA = /[\uE200-\uE2FF]/;
  const markedLib = globalThis.marked;
  const MAX_ARCHIVE_URL_LENGTH = 1000;

  const esc = (s) =>
    String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
  const mdLabel = (s) => String(s ?? "").replace(/([\[\]|\\])/g, "\\$1").replace(/\s+/g, " ").trim();
  const mdUrl = (u) => String(u ?? "").replace(/[\s()<>]/g, (c) => encodeURIComponent(c));

  // Raw HTML that may be present in a response is displayed, never interpreted.
  markedLib.use({
    gfm: true,
    renderer: {
      html(t) {
        return esc(typeof t === "string" ? t : (t && t.text) || "");
      },
    },
  });

  function hostOf(url) {
    try {
      return new URL(url).hostname.replace(/^www\./, "");
    } catch {
      return "";
    }
  }

  // Signed/widget URLs generated by ChatGPT are not useful archive links: they
  // are temporary, frequently enormous, and tend to expire.  Keep normal web
  // sources (Amazon, publishers, news sites, etc.) but never serialize those
  // ephemeral OpenAI CDN URLs into Markdown/HTML.
  function isTemporaryOpenAIUrl(url) {
    try {
      const host = new URL(String(url || "")).hostname.toLowerCase();
      return (
        host === "cdn.platform.openai.com" ||
        host === "cdn.openai.com" ||
        host.endsWith(".oaiusercontent.com") ||
        (host.startsWith("cdn.") && host.endsWith(".openai.com"))
      );
    } catch {
      return false;
    }
  }

  function isArchiveSafeUrl(url) {
    const value = String(url || "").trim();
    if (!/^https?:\/\//i.test(value)) return true; // local/sandbox paths are handled elsewhere
    if (value.length > MAX_ARCHIVE_URL_LENGTH) return false;
    return !isTemporaryOpenAIUrl(value);
  }

  function droppedLinkLabel(label) {
    const text = String(label || "").trim();
    // A descriptive label remains useful even when its temporary target is
    // removed. A hostname/URL label is only noise once the href is gone.
    if (!text || /^https?:\/\//i.test(text) || /^(?:www\.)?[a-z0-9.-]+\.[a-z]{2,}(?:\/.*)?$/i.test(text)) return "";
    return text;
  }

  function sanitizeMarkdownLinks(text) {
    let out = String(text || "");
    const remote = "https?:\\/\\/[^\\s)]+(?:\\([^)]*\\)[^\\s)]*)?";
    const imageRe = new RegExp(`!\\[([^\\]]*)\\]\\((${remote})\\)`, "g");
    const linkRe = new RegExp(`\\[([^\\]]*)\\]\\((${remote})\\)`, "g");
    out = out.replace(imageRe, (match, _label, url) => (isArchiveSafeUrl(url) ? match : ""));
    out = out.replace(linkRe, (match, label, url, offset, whole) => {
      // Do not re-process the inner [alt](url) of an image that survived the
      // first pass.
      if (offset > 0 && whole[offset - 1] === "!") return match;
      return isArchiveSafeUrl(url) ? match : droppedLinkLabel(label);
    });
    out = out.replace(/<(https?:\/\/[^>\s]+)>/g, (match, url) => (isArchiveSafeUrl(url) ? match : ""));
    out = out.replace(/(^|[\s(])(https?:\/\/[^\s<>()\]]+)(?=$|[\s)\]])/gm, (match, prefix, url) =>
      isArchiveSafeUrl(url) ? match : prefix
    );
    // Clean the common residue produced by a removed citation/widget link.
    return out.replace(/\(\s*\)/g, "").replace(/[ \t]+\n/g, "\n").replace(/\n{3,}/g, "\n\n");
  }

  // ---------- Parcours de l’arbre ----------

  // Messages are stored as a tree (regenerations, edits): walk back from
  // the current node to obtain exactly the displayed thread.
  function linearize(conv, startNode = null) {
    const out = [];
    let nodeId = startNode || conv.current_node;
    while (nodeId && conv.mapping[nodeId]) {
      const node = conv.mapping[nodeId];
      if (node.message) out.push(node.message);
      nodeId = node.parent;
    }
    return out.reverse();
  }

  const isImagePart = (p) => p && typeof p === "object" && p.content_type === "image_asset_pointer";
  const isCanvasPart = (p) => p && typeof p === "object" && p.content_type === "canvas_asset_pointer";
  const isFilePart = (p) => p && typeof p === "object" && /file_asset_pointer|audio_asset_pointer|video_asset_pointer|file_pointer|artifact/.test(p.content_type || "");
  const visibleToolTypes = new Set(["text","multimodal_text","code","execution_output","computer_output","reasoning_recap","system_error","super_widget","sonic_webpage","tether_quote","tether_browsing_display"]);

  function isVisible(msg) {
    const role = msg.author && msg.author.role;
    if (msg.metadata && msg.metadata.is_visually_hidden_from_conversation) return false;
    if (role === "tool") {
      const c = msg.content || {};
      const parts = c.parts || [];
      return visibleToolTypes.has(c.content_type) || parts.some((p) => isImagePart(p) || isCanvasPart(p) || isFilePart(p));
    }
    if (role !== "user" && role !== "assistant") return false;
    if (msg.recipient && msg.recipient !== "all") return false; // appel d’outil
    return true;
  }

  // ---------- Reference extraction (sources, images, products) ----------

  // Remove the tracking parameter added by ChatGPT (utm_source=chatgpt.com).
  function cleanUrl(url) {
    try {
      const u = new URL(url);
      if (u.searchParams.get("utm_source") === "chatgpt.com") u.searchParams.delete("utm_source");
      return u.href;
    } catch {
      return url;
    }
  }

  // Walk an arbitrary object to find URLs, separated into images and links.
  // This is a safety net for unknown or malformed reference types.
  function deepUrls(obj, out = { images: [], links: [] }, key = "", depth = 0) {
    if (obj == null || depth > 6) return out;
    if (typeof obj === "string") {
      if (/^https?:\/\//.test(obj) && isArchiveSafeUrl(obj)) {
        const isImg = /image|thumb|img|photo|picture|content_url/i.test(key) || /\.(jpe?g|png|webp|gif|avif)(\?|$)/i.test(obj);
        const list = isImg ? out.images : out.links;
        if (!list.includes(obj)) list.push(obj);
      }
    } else if (Array.isArray(obj)) {
      for (const v of obj) deepUrls(v, out, key, depth + 1);
    } else if (typeof obj === "object") {
      for (const [k, v] of Object.entries(obj)) deepUrls(v, out, k, depth + 1);
    }
    return out;
  }

  function linkItems(ref) {
    const raw = [];
    for (const it of [...(ref.items || []), ...(ref.sources || []), ...(ref.fallback_items || [])]) {
      raw.push(it);
      for (const sub of (it && it.supporting_websites) || []) raw.push(sub);
      for (const sub of (it && it.refs) || []) if (sub && sub.url) raw.push(sub);
    }
    const seen = new Set();
    const out = [];
    for (const it of raw) {
      const url = it && (it.url || it.link);
      if (!url) continue;
      const clean = cleanUrl(url);
      if (!isArchiveSafeUrl(clean)) continue;
      if (seen.has(clean)) continue;
      seen.add(clean);
      out.push({ url: clean, title: it.title || "", label: it.attribution || hostOf(clean) || it.title || "source" });
    }
    return out;
  }

  const asUrl = (i) => (typeof i === "string" ? i : i && (i.url || i.content_url || i.image_url));

  function imageItems(ref) {
    const list = ref.images || ref.image_results || ref.items || [];
    let out = list
      .map((im) => {
        if (typeof im === "string") return isArchiveSafeUrl(im) ? { candidates: [im], title: "", page: "" } : { candidates: [], title: "", page: "" };
        let candidates = [im.content_url, im.image_url, im.original, im.src, im.thumbnail_url, im.thumbnail].filter(
          (u) => typeof u === "string" && isArchiveSafeUrl(u)
        );
        if (!candidates.length) candidates = deepUrls(im).images;
        const page = cleanUrl(im.url || im.page_url || im.source_url || "");
        return { candidates, title: im.title || im.alt || "", page: isArchiveSafeUrl(page) ? page : "" };
      })
      .filter((x) => x.candidates.length);
    if (!out.length) out = deepUrls(ref).images.map((u) => ({ candidates: [u], title: "", page: "" }));
    return out;
  }

  function productItems(ref) {
    const list = ref.products || ref.items || (ref.product ? [ref.product] : []);
    return list.map((p) => {
      const imgs = p.image_urls || p.images || (p.image_url && [p.image_url]) || [];
      const offer = (p.offers && p.offers[0]) || (p.merchants && p.merchants[0]) || {};
      const found = deepUrls(p);
      const price = [p.price, offer.price, p.price_text].find((x) => typeof x === "string" && x) || "";
      const productUrl = cleanUrl(p.url || offer.url || found.links[0] || "");
      const image = imgs.map(asUrl).find((u) => u && isArchiveSafeUrl(u)) || found.images[0] || null;
      return {
        title: p.title || p.name || "Produit",
        url: isArchiveSafeUrl(productUrl) ? productUrl : "",
        price,
        desc:
          [p.description, p.rationale, p.summary, p.tagline, p.subtitle, p.snippet, p.featured_tag, p.caption].find(
            (x) => typeof x === "string" && x
          ) || "",
        image,
      };
    });
  }

  // Entity markers without an associated reference contain JSON ["type", "Name", …].
  function clean(text) {
    return text
      .replace(/\uE200entity\uE202(.*?)\uE201/g, (_, json) => {
        try {
          const arr = JSON.parse(json);
          return Array.isArray(arr) ? String(arr[1] ?? "") : "";
        } catch {
          return "";
        }
      })
      .replace(/\uE200[^\uE201]*\uE201/g, "")
      .replace(/[\uE200-\uE2FF]/g, "");
  }

  // ---------- Rendu d’un texte d’assistant ----------

  // Returns { md, html }: markers are replaced with Markdown on one side,
  // and CGXT<n>Z tokens (converted to HTML after marked) on the other.
  function linksInData(value, out = [], depth = 0) {
    if (value == null || depth > 12) return out;
    if (Array.isArray(value)) {
      for (const child of value) linksInData(child, out, depth + 1);
    } else if (typeof value === "object") {
      const url = value.url || value.link || value.href || value.canonical_url;
      if (typeof url === "string" && /^https?:\/\//i.test(url) && isArchiveSafeUrl(url)) {
        out.push({ url: cleanUrl(url), title: value.title || value.name || "", label: value.attribution || hostOf(url) || value.title || "source" });
      } else {
        for (const child of Object.values(value)) linksInData(child, out, depth + 1);
      }
    }
    return out;
  }

  function citationLinksFromData(ids, data) {
    const wanted = Array.isArray(ids) ? ids.map(String) : [];
    const found = [];
    const seen = new Set();
    const add = (items) => {
      for (const link of items) if (!seen.has(link.url)) { seen.add(link.url); found.push(link); }
    };
    const walk = (value, key = "", depth = 0) => {
      if (value == null || depth > 12) return;
      if (Array.isArray(value)) {
        value.forEach((child, index) => walk(child, String(index), depth + 1));
        return;
      }
      if (typeof value !== "object") return;
      const directValues = Object.values(value).filter((child) => typeof child === "string");
      if (wanted.some((id) => key === id || key.includes(id) || directValues.includes(id))) {
        add(linksInData(value));
        return;
      }
      for (const [childKey, child] of Object.entries(value)) walk(child, childKey, depth + 1);
    };
    walk(data);
    return found;
  }

  function resolveCitationLinks(ids, refs, extraData = null) {
    const wanted = Array.isArray(ids) ? ids.map(String) : [];
    const matched = (refs || []).filter((ref) => {
      let serialized = "";
      try { serialized = JSON.stringify(ref); } catch (_) {}
      return wanted.some((id) => serialized.includes(id));
    });
    const collect = (list) => {
      const seen = new Set();
      return list.flatMap((ref) => [...linkItems(ref), ...linksInData(ref)]).filter((link) => {
        if (seen.has(link.url)) return false;
        seen.add(link.url);
        return true;
      });
    };
    const exact = [...citationLinksFromData(wanted, extraData), ...collect(matched)];
    const uniqueExact = exact.filter((link, index, list) => list.findIndex((item) => item.url === link.url) === index);
    // Some ChatGPT builds keep citation URLs on a grouped reference object
    // without retaining the turn/search ID. In that case, preserve the URLs
    // exposed by this message rather than leaking opaque turn IDs into notes.
    return uniqueExact.length ? uniqueExact : collect(refs || []);
  }

  function dedentRichComponentMarkup(text) {
    const lines = String(text || "").split("\n");
    const componentTag = /<\/?(box|row|text|title|divider|caption|list|list-item)\b[^>]*>/gi;
    let depth = 0;
    return lines.map((line) => {
      const insideComponent = depth > 0;
      const normalized = insideComponent ? line.trimStart() : line;
      for (const match of line.matchAll(componentTag)) {
        const tag = match[0];
        if (/^<\//.test(tag)) depth = Math.max(0, depth - 1);
        else if (!/\/>$/.test(tag)) depth += 1;
      }
      return normalized;
    }).join("\n");
  }

  function preprocessRichComponents(text, refs = [], extraData = null, ctx = null) {
    if (extraData && extraData.jexRichHtml) {
      return preprocessJexRichComponents(text, refs, extraData, ctx);
    }
    let out = dedentRichComponentMarkup(text);
    // ChatGPT sometimes serializes Markdown table row breaks as HTML <br>
    // tags. Markdown parsers require actual newlines between table rows.
    out = out.replace(/<br\s*\/?>[ \t]*(?=\|)/gi, "\n");
    out = out.replace(/<Cite\b[^>]*\brefs=\{(\[[\s\S]*?\])\}\s*\/?\s*>/g, (_match, rawIds) => {
      let ids = [];
      try { ids = JSON.parse(rawIds); } catch (_) {}
      const links = resolveCitationLinks(ids, refs, extraData);
      if (links.length) return ` (Sources: ${links.map((link) => `[${mdLabel(link.title || link.label)}](${mdUrl(link.url)})`).join(", ")})`;
      return " (Citation links could not be resolved from the data available to the exporter.)";
    });

    out = out.replace(/\{#each\s+Array\.from\(\{\s*length\s*:\s*(\d+)\s*\}\)[\s\S]*?\{\/each\}/g, (block, rawCount) => {
      const count = Number(rawCount);
      const highlighted = new Set([...block.matchAll(/i\s*===\s*(\d+)/g)].map((match) => Number(match[1])));
      const filled = count ? Math.round(Math.min(count, highlighted.size) * 12 / count) : 0;
      return `\n\nDiagram: ${"█".repeat(filled)}${"░".repeat(12 - filled)} (${highlighted.size} of ${count} blocks highlighted).\n\n`;
    });
    out = out.replace(/<box\b([^>]*?)\bwidth=["']([\d.]+)%["'][^>]*\/?\s*>/gi, (_match, attrs, rawPercent) => {
      const percent = Math.max(0, Math.min(100, Number(rawPercent)));
      if (extraData && extraData.jexCompactHtml) {
        const rawColor = attrs.match(/\bbackground=["']([^"']+)["']/i)?.[1] || "#64748B";
        const color = /^#[0-9a-f]{3,8}$/i.test(rawColor) ? rawColor : "#64748B";
        return `\n\n<div style="height:8px;width:100%;border-radius:999px;background:linear-gradient(90deg,${color} ${percent}%,#27272a ${percent}%);"></div>\n\n`;
      }
      return `Relative throughput: ${percent}%`;
    });
    const asyncImages = extraData && extraData.message && extraData.message.metadata && extraData.message.metadata.cgx_dom_async_images || [];
    const usedAsyncImages = new Set();
    out = out.replace(/<AsyncImage\b([^>]*)\/?\s*>/gi, (_match, attrs) => {
      const query = attrs.match(/\bquery\s*=\s*["']([^"']*)["']/i)?.[1];
      let imageIndex = asyncImages.findIndex((candidate, index) => !usedAsyncImages.has(index) && candidate.query === query);
      if (imageIndex < 0) imageIndex = asyncImages.findIndex((_candidate, index) => !usedAsyncImages.has(index));
      const image = imageIndex >= 0 ? asyncImages[imageIndex] : null;
      if (image && image.url && ctx) {
        usedAsyncImages.add(imageIndex);
        const placeholder = ctx.image([image.url], false);
        return `\n\n![${mdLabel(image.alt || "Generated illustration")}](${placeholder})\n\n`;
      }
      const alt = image && image.alt || query;
      return alt ? `\n\n*Illustration unavailable: ${alt.trim()}*\n\n` : "";
    });
    out = out.replace(/<divider\b[^>]*\/?\s*>/gi, "\n\n---\n\n");
    out = out.replace(/<list\b[^>]*\bmarker=["']number["'][^>]*>([\s\S]*?)<\/list>/gi, (_match, body) => {
      let number = 0;
      return body.replace(/<list-item\b[^>]*>([\s\S]*?)<\/list-item>/gi, (_item, content) => `${++number}. ${content.trim()}\n`);
    });
    out = out.replace(/<list\b[^>]*>([\s\S]*?)<\/list>/gi, (_match, body) =>
      body.replace(/<list-item\b[^>]*>([\s\S]*?)<\/list-item>/gi, (_item, content) => `- ${content.trim()}\n`)
    );
    out = out.replace(/<caption\b[^>]*>([\s\S]*?)<\/caption>/gi, (_match, body) => `\n\n*${body.trim()}*\n\n`);
    out = out.replace(/<title\b[^>]*>([\s\S]*?)<\/title>/gi, (_match, body) => `**${body.trim()}**`);
    out = out.replace(/<row\b([^>]*)>([\s\S]*?)<\/row>/gi, (_match, attrs, body) => {
      if (/\bjustify=["']between["']/i.test(attrs) && !/<(?:AsyncImage|list)\b/i.test(body)) {
        const inline = body.trim().replace(/\*\*\*\*/g, "** | **").replace(/\s*\n\s*/g, " | ").replace(/(?:\s*\|\s*){2,}/g, " | ").replace(/\s+/g, " ");
        return `\n\n${inline}\n\n`;
      }
      return `\n${body.trim()}\n`;
    });
    out = out.replace(/<\/?(?:box|text)\b[^>]*>/gi, "\n");
    out = out.replace(/\n[ \t]*\n(?:[ \t]*\n)+/g, "\n\n");
    return out;
  }

  // Keep ChatGPT's rich cards in Joplin's Markdown note as ordinary inline
  // HTML. Joplin renders HTML inside Markdown notes, and JEX resource paths
  // are rewritten later by content.js just like Markdown image paths.
  function preprocessJexRichComponents(text, refs = [], extraData = null, ctx = null) {
    let source = dedentRichComponentMarkup(text);
    const generatedHtml = new Map();
    const keepHtml = (value) => {
      const token = `CGXJEXHTML${generatedHtml.size}Z`;
      generatedHtml.set(token, value);
      return token;
    };
    source = source.replace(/<Cite\b[^>]*\brefs=\{(\[[\s\S]*?\])\}\s*\/?\s*>/g, (_m, raw) => {
      let ids = []; try { ids = JSON.parse(raw); } catch (_) {}
      const links = resolveCitationLinks(ids, refs, extraData);
      return links.length ? links.map((link) => `[${mdLabel(link.title || link.label)}](${mdUrl(link.url)})`).join(" · ") : "";
    });
    const asyncImages = extraData?.message?.metadata?.cgx_dom_async_images || [];
    const usedImages = new Set();
    source = source.replace(/<AsyncImage\b([^>]*)\/?\s*>/gi, (_m, attrs) => {
      const query = attrs.match(/\bquery\s*=\s*["']([^"']*)["']/i)?.[1];
      let index = asyncImages.findIndex((item, i) => !usedImages.has(i) && item.query === query);
      if (index < 0) index = asyncImages.findIndex((_item, i) => !usedImages.has(i));
      const image = index >= 0 ? asyncImages[index] : null;
      if (!image?.url || !ctx) return image?.alt || query || "";
      usedImages.add(index);
      const maxWidthRaw = attrs.match(/\bmaxWidth\s*=\s*["']([^"']+)["']/i)?.[1] || "";
      const maxWidth = /^(?:\d+(?:\.\d+)?)(?:px|em|rem|%)$/.test(maxWidthRaw) ? maxWidthRaw : "";
      const ratioRaw = attrs.match(/\baspectRatio\s*=\s*["']([^"']+)["']/i)?.[1] || "";
      const ratioMatch = ratioRaw.match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
      const ratio = ratioMatch ? `${ratioMatch[1]}/${ratioMatch[2]}` : "";
      return keepHtml(`<img src="${ctx.image([image.url], false)}" alt="${esc(image.alt || query || "Generated illustration")}" style="display:block;width:100%;${maxWidth ? `max-width:${maxWidth};` : ""}${ratio ? `aspect-ratio:${ratio};` : ""}height:auto;object-fit:cover;border-radius:12px;">`);
    });
    source = source.replace(/\{#each\s+Array\.from\(\{\s*length\s*:\s*(\d+)\s*\}\)[\s\S]*?\{\/each\}/g, (block, countText) => {
      const count = Number(countText);
      const highlighted = new Set([...block.matchAll(/i\s*===\s*(\d+)/g)].map((m) => Number(m[1])));
      const percent = count ? Math.round(Math.min(count, highlighted.size) * 100 / count) : 0;
      return keepHtml(`<div style="display:flex;gap:3px;margin:8px 0;">${Array.from({length:Math.min(count, 60)}, (_x, i) => `<span style="display:block;flex:1;height:12px;border-radius:2px;background:${highlighted.has(i) ? "#16A34A" : "#64748B"};opacity:${highlighted.has(i) ? "1" : ".3"};"></span>`).join("")}</div><small>${percent}% highlighted (${highlighted.size} of ${count})</small>`);
    });

    const cssLength = (value) => {
      if (/^\d+(?:\.\d+)?$/.test(value || "")) return `${Number(value) * 4}px`;
      return /^(?:\d+(?:\.\d+)?)(?:px|em|rem|%)$/.test(value || "") ? value : "";
    };
    const stylesFor = (tag, attrs) => {
      const get = (name) => attrs.match(new RegExp(`\\b${name}\\s*=\\s*(?:["']([^"']*)["']|\\{([^}]*)\\})`, "i"))?.slice(1).find((value) => value != null) || "";
      if (tag === "box") {
        const styles = ["box-sizing:border-box", "display:flex", "flex-direction:column"];
        const gap = get("gap"); if (gap) styles.push(`gap:${cssLength(gap) || `calc(var(--spacing, 1rem) * ${Number(gap) || 1})`}`);
        if (/\bborder(?:\s|=|$)/i.test(attrs) && get("border") !== "false") styles.push("border:1px solid #3f3f46");
        if (get("radius")) styles.push(`border-radius:${get("radius") === "full" ? "9999px" : "12px"}`);
        if (get("padding") || get("p")) styles.push(`padding:${cssLength(get("padding") || get("p")) || "16px"}`);
        if (get("background")) styles.push(`background:${get("background").includes("tertiary") ? "#27272a" : /^#[0-9a-f]{3,8}$/i.test(get("background")) ? get("background") : "transparent"}`);
        if (get("flex")) styles.push(`flex:${/^\d+(?:\.\d+)?$/.test(get("flex")) ? get("flex") : cssLength(get("flex"))}`);
        if (get("width")) styles.push(`width:${cssLength(get("width"))}`);
        if (get("height")) styles.push(`height:${cssLength(get("height"))}`);
        if (/\bclip\b/i.test(attrs)) styles.push("overflow:hidden");
        return styles.join(";");
      }
      if (tag === "row") return `display:flex;align-items:${get("align") === "start" ? "flex-start" : "center"};justify-content:${get("justify") === "between" ? "space-between" : "flex-start"};gap:${cssLength(get("gap")) || "12px"};flex-wrap:wrap`;
      if (tag === "divider") return "border:0;border-top:1px solid #3f3f46;margin:16px 0";
      if (tag === "title") return `font-size:${get("size") === "lg" ? "1.15em" : "1em"};font-weight:700;color:${get("color") === "success" ? "#22c55e" : "inherit"}`;
      if (tag === "text" || tag === "caption") return `color:${get("color") === "secondary" ? "#a1a1aa" : "inherit"};font-size:${get("size") === "sm" ? ".9em" : "inherit"}`;
      if (tag === "code") return "font-family:monospace;background:#27272a;padding:2px 5px;border-radius:4px";
      return "";
    };
    const tagRe = /<(\/?)(box|row|text|title|divider|caption|list|list-item|bold|italic|code|link)\b([^>]*?)\s*(\/?)>/gi;
    let html = "", cursor = 0;
    const renderText = (chunk) => {
      if (!chunk) return "";
      let s = esc(chunk).replace(/\*\*(.+?)\*\*/gs, "<strong>$1</strong>").replace(/(?<!\*)\*([^*\n]+)\*(?!\*)/g, "<em>$1</em>");
      s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_m, label, url) => `<a href="${esc(url)}">${label}</a>`);
      return s.split(/\n{2,}/).map((paragraph) => {
        const lines = paragraph.split("\n"), parts = [];
        let bullets = [];
        const flushBullets = () => {
          if (bullets.length) parts.push(`<ul style="margin:8px 0;padding-left:1.4em;">${bullets.map((line) => `<li style="margin:4px 0;">${line.replace(/^\s*[-*]\s+/, "")}</li>`).join("")}</ul>`);
          bullets = [];
        };
        let prose = [];
        const flushProse = () => { if (prose.length) parts.push(prose.join("<br>")); prose = []; };
        for (const line of lines) {
          if (/^\s*[-*]\s+/.test(line)) { flushProse(); bullets.push(line); }
          else { flushBullets(); if (line.trim()) prose.push(line.trim()); }
        }
        flushProse(); flushBullets();
        return parts.join("");
      }).filter(Boolean).join("\n");
    };
    for (const match of source.matchAll(tagRe)) {
      const [raw, closing, tagName, rawAttrs, selfClosing] = match;
      html += renderText(source.slice(cursor, match.index));
      const tag = tagName.toLowerCase();
      const attrs = rawAttrs || "";
      if (tag === "divider") html += `<hr style="${stylesFor(tag, attrs)}">`;
      else if (closing) html += `</${tag === "row" || tag === "box" ? "div" : tag === "caption" ? "p" : tag === "list-item" ? "li" : tag === "list" ? "ul" : tag === "bold" ? "strong" : tag === "italic" ? "em" : tag === "code" ? "code" : tag === "link" ? "a" : "span"}>`;
      else {
        const element = tag === "row" || tag === "box" ? "div" : tag === "caption" ? "p" : tag === "list" ? "ul" : tag === "list-item" ? "li" : tag === "bold" ? "strong" : tag === "italic" ? "em" : tag === "code" ? "code" : tag === "link" ? "a" : "span";
        const href = tag === "link" ? attrs.match(/\bhref\s*=\s*["']([^"']+)["']/i)?.[1] : "";
        const safeHref = href && /^(?:https?:\/\/|mailto:|#)/i.test(href) ? ` href="${esc(href)}"` : "";
        html += `<${element}${safeHref}${stylesFor(tag, attrs) ? ` style="${stylesFor(tag, attrs)}"` : ""}>`;
        if (selfClosing) html += `</${element}>`;
      }
      cursor = match.index + raw.length;
    }
    html += renderText(source.slice(cursor));
    html = html.replace(/(?:\s*<br>\s*){3,}/g, "<br><br>");
    for (const [token, markup] of generatedHtml) html = html.split(token).join(markup);
    return html;
  }

  function preprocessWritingBlocks(text, refs = [], extraData = null, ctx = null) {
    return preprocessRichComponents(text, refs, extraData, ctx).replace(/:::writing\{([^}]*)\}\s*([\s\S]*?)\s*:::/g, (_m, meta, body) => {
      const attrs = {};
      for (const m of meta.matchAll(/([a-zA-Z_]+)="([^"]*)"/g)) attrs[m[1]] = m[2];
      const label = attrs.subject || attrs.title || attrs.variant || "Writing block";
      return `\n\n> **${label}**\n>\n${String(body).trim().split("\n").map((x) => `> ${x}`).join("\n")}\n\n`;
    });
  }

  function fileRefInfo(ref) {
    const f = ref.file || {};
    const id = ref.file_id || ref.asset_id || ref.upload_id || f.id || f.file_id || f.asset_id;
    const name = ref.file_name || ref.filename || ref.title || f.name || f.filename || "file";
    const page = ref.page_number || ref.page || (ref.location && ref.location.page);
    const start = ref.start_line || (ref.location && ref.location.start_line);
    const end = ref.end_line || (ref.location && ref.location.end_line);
    const sandboxPath = ref.sandbox_path || f.sandbox_path || null;
    const messageId = ref.message_id || f.message_id || null;
    const urls = [ref.url, ref.download_url, ref.signed_url, ref.href, f.url, f.download_url, f.signed_url, f.href].filter((x) => typeof x === "string" && x);
    return { id, name, page, start, end, sandboxPath, messageId, urls };
  }

  function renderRichText(text, refs, ctx, messageId = null, metadata = null) {
    text = preprocessWritingBlocks(text, refs, metadata, ctx);
    // Sandbox links are files generated by ChatGPT. Replace them with a file
    // marker so content.js can try sandbox endpoints, then keep the original
    // link if no endpoint is available for the account.
    text = String(text).replace(/\[([^\]]+)\]\((sandbox:\/[^)]+)\)/g, (_m, label, url) => {
      const ph = ctx.file([url], label || "file", { messageId, sandboxPath: url.replace(/^sandbox:/, "") });
      return `[${label}](${ph})`;
    });
    let md = text;
    let src = text;
    const tokens = new Map();
    const token = (html, block) => {
      const t = `CGXT${tokens.size}Z`;
      tokens.set(t, html);
      return block ? `\n\n${t}\n\n` : t;
    };

    const sorted = refs
      .filter((r) => r && typeof r.matched_text === "string" && PUA.test(r.matched_text))
      .sort((a, b) => b.matched_text.length - a.matched_text.length);

    const galleryHtml = (imgs) =>
      `<div class="gallery">${imgs
        .map((i) => `<a href="${esc(i.page || i.ph)}" title="${esc(i.title)}"><img src="${i.ph}" alt="${esc(i.title)}" loading="lazy"></a>`)
        .join("")}</div>`;
    const galleryMd = (imgs) =>
      "\n\n" +
      imgs.map((i) => (i.page ? `[![${mdLabel(i.title)}](${i.ph})](${mdUrl(i.page)})` : `![${mdLabel(i.title)}](${i.ph})`)).join(" ") +
      "\n\n";
    const citeHtml = (links) => {
      const first = links[0];
      const pop =
        links.length > 1
          ? `<span class="pop">${links.map((l) => `<a href="${esc(l.url)}">${esc(l.title || l.label)}<small>${esc(hostOf(l.url))}</small></a>`).join("")}</span>`
          : "";
      return (
        `<span class="cite"><a href="${esc(first.url)}" title="${esc(first.title || first.url)}">${esc(first.label)}` +
        (links.length > 1 ? `<span class="more">+${links.length - 1}</span>` : "") +
        `</a>${pop}</span>`
      );
    };
    const citeMd = (links) => ` (${links.map((l) => `[${mdLabel(l.label)}](${mdUrl(l.url)})`).join(", ")})`;

    for (const ref of sorted) {
      const type = ref.type || "";
      let mdOut = "";
      let srcOut = "";

      if (type === "hidden" || type === "attribution") {
        // rien
      } else if (/product/.test(type)) {
        const prods = productItems(ref).map((p) => ({ ...p, ph: p.image ? ctx.image([p.image], false) : null }));
        mdOut =
          "\n\n" +
          prods
            .map((p) => {
              const img = p.ph ? (p.url ? `[![${mdLabel(p.title)}](${p.ph})](${mdUrl(p.url)})\n` : `![${mdLabel(p.title)}](${p.ph})\n`) : "";
              const name = p.url ? `**[${mdLabel(p.title)}](${mdUrl(p.url)})**` : `**${mdLabel(p.title)}**`;
              const extra = [p.price, p.desc].filter(Boolean).join(". ");
              return `${img}${name}${extra ? " : " + extra : ""}`;
            })
            .join("\n\n") +
          "\n\n";
        srcOut = token(
          `<div class="carousel">${prods
            .map((p) => {
              const tag = p.url ? "a" : "div";
              const href = p.url ? ` href="${esc(p.url)}"` : "";
              return (
                `<${tag} class="product"${href}>` +
                (p.ph ? `<img src="${p.ph}" alt="" loading="lazy">` : `<span class="noimg"></span>`) +
                `<strong>${esc(p.title)}</strong>` +
                `<span class="meta">${[p.price, p.desc].filter(Boolean).map(esc).join(" • ")}</span>` +
                `</${tag}>`
              );
            })
            .join("")}</div>`,
          true
        );
      } else if (/file|filecite/.test(type)) {
        const info = fileRefInfo(ref);
        const candidates = [];
        if (info.id) candidates.push(`asset:${String(info.id).replace(/^file-service:\/\//, "")}`);
        if (info.sandboxPath) candidates.push(`sandbox:${info.sandboxPath}`);
        candidates.push(...info.urls);
        const ph = candidates.length ? ctx.file(candidates, info.name, { messageId: info.messageId || messageId, sandboxPath: info.sandboxPath }) : null;
        const loc = [info.page != null ? `p. ${info.page}` : "", info.start != null ? `l. ${info.start}${info.end != null ? `-${info.end}` : ""}` : ""].filter(Boolean).join(", ");
        const label = `${info.name}${loc ? ` (${loc})` : ""}`;
        mdOut = ph ? ` [${mdLabel(label)}](${ph})` : ` [${mdLabel(label)}]`;
        srcOut = ph ? `<a class="filecite" href="${ph}">${esc(label)}</a>` : `<span class="filecite">${esc(label)}</span>`;
      } else if (/image/.test(type)) {
        const imgs = imageItems(ref).map((i) => ({ ...i, ph: ctx.image(i.candidates, false) }));
        if (imgs.length) {
          mdOut = galleryMd(imgs);
          srcOut = token(galleryHtml(imgs), true);
        }
      } else if (type === "entity") {
        mdOut = srcOut = ref.alt || ref.name || "";
      } else {
        const links = linkItems(ref);
        if (links.length) {
          mdOut = citeMd(links);
          srcOut = " " + token(citeHtml(links), false);
        } else if (typeof ref.alt === "string" && ref.alt) {
          mdOut = srcOut = ref.alt;
        } else {
        // Unknown type: recover at least the images and links it contains.
          const found = deepUrls(ref);
          if (found.images.length) {
            const imgs = found.images.map((u) => ({ candidates: [u], title: "", page: "", ph: ctx.image([u], false) }));
            mdOut = galleryMd(imgs);
            srcOut = token(galleryHtml(imgs), true);
          } else if (found.links.length) {
            const links = found.links.map((u) => ({ url: cleanUrl(u), title: "", label: hostOf(u) || "lien" }));
            mdOut = citeMd(links);
            srcOut = " " + token(citeHtml(links), false);
          }
        }
      }

      md = md.split(ref.matched_text).join(mdOut);
      src = src.split(ref.matched_text).join(srcOut);
    }

    md = sanitizeMarkdownLinks(clean(md)).replace(/ {2,}\(\[/g, " ([").replace(/\n{3,}/g, "\n\n").trim();
    let html = markedLib.parse(sanitizeMarkdownLinks(clean(src)).replace(/ {2,}(CGXT\d+Z)/g, " $1").trim());
    for (const [t, h] of tokens) html = html.split(`<p>${t}</p>`).join(h).split(t).join(h);
    html = html.replace(/<table>/g, '<div class="table-wrap"><table>').replace(/<\/table>/g, "</table></div>");
    return { md, html };
  }

  // ---------- Rendu d’un message ----------

  function thinkingSeconds(text) {
    const source = String(text || '').toLowerCase().replace(',', '.');
    let total = 0;
    for (const match of source.matchAll(/(\d+(?:\.\d+)?)\s*(h|hr|hrs|hour|hours|heure|heures|m|min|mins|minute|minutes|s|sec|secs|second|seconds|seconde|secondes)/gi)) {
      const value = Number(match[1]);
      const unit = match[2];
      total += /^(h|hr|hrs|hour|hours|heure|heures)$/.test(unit) ? value * 3600 : /^(m|min|mins|minute|minutes)$/.test(unit) ? value * 60 : value;
    }
    return total;
  }

  function isThinkingDurationOnly(text) {
    return /^(?:worked|thought|reasoned|réfléchi|reflechi|temps de réflexion|thinking)\s*(?:for|pendant|:)?\s*\d+(?:[.,]\d+)?\s*(?:h|hr|hrs|hour|hours|heure|heures|m|min|mins|minute|minutes|s|sec|secs|second|seconds|seconde|secondes)$/i.test(String(text || '').trim().replace(/^\*+|\*+$/g, ''));
  }

  function renderMessage(msg, ctx, options = {}) {
    const role = msg.author.role === "user" ? "user" : "assistant";
    const c = msg.content || {};
    const refs = (msg.metadata && msg.metadata.content_references) || [];
    const mdParts = [];
    const htmlParts = [];

    const addText = (text) => {
      if (!text || !text.trim()) return;
      if (role === "user") {
        // ChatGPT displays user messages as-is, without Markdown interpretation.
        const t = clean(text).trim();
        mdParts.push(t);
        htmlParts.push(`<div class="plain">${esc(t)}</div>`);
      } else {
        // DIL citations may be bound outside metadata.content_references.
        // Pass the full message so the renderer can resolve IDs from any
        // message-level citation/model-data bindings without exporting them.
        const r = renderRichText(text, refs, ctx, msg.id || null, {
          message: msg,
          conversation: options.citationData || null,
          jexRichHtml: !!options.jexRichHtml,
          jexCompactHtml: !!options.jexCompactHtml,
        });
        if (r.md) mdParts.push(r.md);
        if (r.html.trim()) htmlParts.push(r.html);
      }
    };

    const addAsset = (part) => {
      const id = String(part.asset_pointer || "").replace(/^[a-z-]+:\/\//, "");
      if (!id) return;
      const prompt = (part.metadata && part.metadata.dalle && part.metadata.dalle.prompt) || "";
      const ph = ctx.image([`asset:${id}`], true);
      mdParts.push(`![${mdLabel(prompt || "image")}](${ph})`);
      htmlParts.push(`<figure class="asset"><img src="${ph}" alt="${esc(prompt)}" loading="lazy"></figure>`);
    };

    const addFileAsset = (part, fallback = "file") => {
      const id = String(part.asset_pointer || part.file_id || part.asset_id || "").replace(/^[a-z-]+:\/\//, "");
      const name = part.name || part.filename || part.file_name || (part.metadata && (part.metadata.name || part.metadata.filename || part.metadata.file_name)) || fallback;
      const sandboxPath = part.sandbox_path || (part.metadata && part.metadata.sandbox_path) || null;
      const messageId = part.message_id || (part.metadata && part.metadata.message_id) || msg.id || null;
      const candidates = [];
      if (id) candidates.push(`asset:${id}`);
      if (sandboxPath) candidates.push(`sandbox:${sandboxPath}`);
      for (const u of [part.url, part.download_url, part.signed_url, part.href]) if (typeof u === "string" && u) candidates.push(u);
      if (!candidates.length) return;
      const ph = ctx.file(candidates, name, { messageId, sandboxPath });
      mdParts.push(`[${mdLabel(name)}](${ph})`);
      htmlParts.push(`<p class="attachment"><a href="${ph}">${esc(name)}</a></p>`);
    };

    switch (c.content_type) {
      case "text":
        addText((c.parts || []).filter((p) => typeof p === "string").join("\n\n"));
        break;
      case "multimodal_text":
        for (const p of c.parts || []) {
          if (typeof p === "string") addText(p);
          else if (isImagePart(p)) addAsset(p);
          else if (isCanvasPart(p) || isFilePart(p)) addFileAsset(p, isCanvasPart(p) ? "canvas" : "file");
        }
        break;
      case "reasoning_recap":
        if (!options.thinking) return null;
        if (typeof c.content === "string" && c.content.trim()) return { kind: "thinking", text: c.content.trim(), seconds: thinkingSeconds(c.content) };
        break;
      case "code":
        if (c.text) addText("```" + (c.language && c.language !== "unknown" ? c.language : "") + "\n" + c.text + "\n```");
        break;
      case "execution_output":
      case "computer_output":
      case "system_error":
        addText(c.text || c.content || (c.parts || []).filter((p) => typeof p === "string").join("\n"));
        break;
      case "super_widget":
      case "sonic_webpage":
      case "tether_quote":
      case "tether_browsing_display": {
        const pieces = [];
        const seen = new Set();
        const walk = (v, key = "", depth = 0) => {
          if (v == null || depth > 5) return;
          if (typeof v === "string") {
            if (/^(title|text|content|snippet|description|caption|label|quote|url|href)$/i.test(key) && v.trim() && !seen.has(v)) { seen.add(v); pieces.push(v); }
            return;
          }
          if (Array.isArray(v)) { for (const x of v) walk(x, key, depth + 1); return; }
          if (typeof v === "object") for (const [k, x] of Object.entries(v)) walk(x, k, depth + 1);
        };
        walk(c);
        if (pieces.length) addText(pieces.join("\n\n"));
        break;
      }
      default:
        if (Array.isArray(c.parts)) for (const p of c.parts) { if (typeof p === "string") addText(p); else if (isImagePart(p)) addAsset(p); else if (isCanvasPart(p) || isFilePart(p)) addFileAsset(p); }
        break;
    }

    const meta = msg.metadata || {};
    const files = [...(Array.isArray(meta.attachments) ? meta.attachments : []), ...(Array.isArray(meta.files) ? meta.files : []), ...(Array.isArray(meta.artifacts) ? meta.artifacts : [])];
    for (const f of files) {
      if (!f || typeof f !== "object" || /^image\//.test(f.mime_type || f.content_type || "")) continue;
      const nested = f.file && typeof f.file === "object" ? f.file : {};
      const name = f.name || f.filename || f.file_name || nested.name || nested.filename || "file";
      const id = f.id || f.file_id || f.asset_id || nested.id || nested.file_id || String(f.asset_pointer || nested.asset_pointer || "").replace(/^[a-z-]+:\/\//, "");
      const sandboxPath = f.sandbox_path || nested.sandbox_path || null;
      const messageId = f.message_id || nested.message_id || msg.id || null;
      const candidates = [];
      if (id) candidates.push(`asset:${String(id).replace(/^file-service:\/\//, "")}`);
      if (sandboxPath) candidates.push(`sandbox:${sandboxPath}`);
      for (const u of [f.url, f.download_url, f.signed_url, f.href, nested.url, nested.download_url, nested.signed_url, nested.href]) if (typeof u === "string" && u) candidates.push(u);
      if (candidates.length) {
        const ph = ctx.file(candidates, name, { messageId, sandboxPath });
        mdParts.push(`*Attachment: [${mdLabel(name)}](${ph})*`);
        htmlParts.push(`<p class="attachment">Attachment: <a href="${ph}">${esc(name)}</a></p>`);
      } else {
        mdParts.push(`*Attachment: ${mdLabel(name)}*`);
        htmlParts.push(`<p class="attachment">Attachment: ${esc(name)}</p>`);
      }
    }

    if (!mdParts.some((part) => String(part).trim()) && !htmlParts.some((part) => String(part).trim())) return null;
    return { role, md: mdParts.join("\n\n"), html: htmlParts.join("\n") };
  }

  // ---------- Documents complets ----------

  // Dates arrive as Unix seconds (conversation) or ISO 8601 (history list).
  function toDate(v) {
    if (v == null || v === "") return null;
    const d = typeof v === "number" ? new Date(v * 1000) : new Date(v);
    return isNaN(d) ? null : d;
  }

  function formatDate(v) {
    const d = toDate(v);
    return d ? d.toLocaleString("en-US") : "unknown date";
  }

  function buildTurns(conv, ctx, nodeId = null, options = {}) {
    let turns = [];
    const thinking = [];
    let totalThinkingSeconds = 0;
    for (const msg of linearize(conv, nodeId)) {
      if (!isVisible(msg)) continue;
      // Some ChatGPT builds put citation/model-data bindings on the
      // conversation response rather than on each individual message.
      const r = renderMessage(msg, ctx, { ...options, citationData: conv });
      if (!r) continue;
      if (r.kind === "thinking") {
        totalThinkingSeconds += r.seconds || 0;
        if (!isThinkingDurationOnly(r.text)) thinking.push(r.text);
        continue;
      }
      turns.push({ role: r.role, md: [r.md], html: [r.html], messageId: msg.id || null, createdAt: msg.create_time || null, sourceRole: msg.author && msg.author.role || r.role });
    }
    if (!options.thinking) {
      // A modern ChatGPT answer can be represented by several consecutive
      // visible nodes: progress/commentary, tool displays, then the definitive
      // assistant answer.  Those intermediate nodes are not the archival answer
      // users expect when "Thinking" is disabled.  Collapse each assistant/tool
      // burst to the last real assistant message before the next user turn.
      const compact = [];
      let pending = [];
      const flush = () => {
        if (!pending.length) return;
        const preferred = [...pending].reverse().find((t) => t.sourceRole === "assistant") || pending[pending.length - 1];
        compact.push(preferred);
        pending = [];
      };
      for (const turn of turns) {
        if (turn.role === "user") {
          flush();
          compact.push(turn);
        } else {
          pending.push(turn);
        }
      }
      flush();
      turns = compact;
    }
    if (options.thinking && (thinking.length || totalThinkingSeconds)) {
      const duration = totalThinkingSeconds ? `*Total thinking time: ${formatThinkingDuration(totalThinkingSeconds)}*` : '';
      const htmlDuration = totalThinkingSeconds ? `<p><em>Total thinking time: ${esc(formatThinkingDuration(totalThinkingSeconds))}</em></p>` : '';
      turns.push({ role: "thinking", md: [[duration, ...thinking].filter(Boolean).join("\n\n")], html: [`${htmlDuration}${thinking.map((text) => `<div class="thought">${esc(text)}</div>`).join("\n")}`], messageId: null, createdAt: null });
    }
    return turns;
  }

  function formatThinkingDuration(seconds) {
    const value = Math.round(seconds);
    const parts = [];
    const hours = Math.floor(value / 3600);
    const minutes = Math.floor((value % 3600) / 60);
    const rest = value % 60;
    if (hours) parts.push(`${hours}h`);
    if (minutes) parts.push(`${minutes}m`);
    if (rest || !parts.length) parts.push(`${rest}s`);
    return parts.join(' ');
  }

  function branchLeaves(conv) {
    const mapping = conv.mapping || {};
    const leaves = [];
    for (const [id, node] of Object.entries(mapping)) {
      if (!node || !node.message) continue;
      const children = Array.isArray(node.children) ? node.children.filter((c) => mapping[c]) : [];
      if (!children.length) leaves.push(id);
    }
    const current = conv.current_node;
    leaves.sort((a, b) => (a === current ? -1 : b === current ? 1 : 0));
    return leaves;
  }

  // A user message becomes a one-cell card, bold, left-aligned and sized to its
  // text. With HTML allowed it is a self-contained one-line <table> block: the
  // only form that can guarantee the background colour and the left alignment,
  // since a Markdown table's header cell inherits whatever the viewer's theme
  // puts on `th`, borders and centring included. Everything the message holds --
  // sent images, attachments, pasted code and tables -- is rendered inside that
  // cell, so every question is a card and needs no role label.
  // The pale blue of the HTML export bubble, kept translucent so it darkens a
  // light theme and lightens a dark one without forcing a text colour.
  const QUESTION_CARD_BG = "rgba(59,130,246,.15)";
  // border:0 and width:auto override the table styling viewers apply by default
  // (Joplin included), so the card is a plain coloured box sized to its text.
  // The short bottom padding compensates the last block's own bottom margin.
  const CARD_TABLE_STYLE = "border-collapse:collapse;border:0;width:auto;max-width:100%;margin:0 0 16px";
  const CARD_CELL_STYLE = `border:0;border-radius:8px;padding:10px 16px 2px;text-align:left;background:${QUESTION_CARD_BG}`;
  const ATTACHMENT_LINK = /^\*Attachment: \[(.*)\]\((.*)\)\*$/;
  const ATTACHMENT_PLAIN = /^\*Attachment: (.*)\*$/;
  const BARE_LINK = /^\[(.*)\]\((.*)\)$/;

  const isAttachmentLine = (line) => ATTACHMENT_LINK.test(line) || ATTACHMENT_PLAIN.test(line) || BARE_LINK.test(line);
  const cellPipes = (line) => line.replace(/\|/g, "\\|");

  // Markdown is not parsed inside an HTML block, so the message is rendered to
  // HTML first. Prose is bolded the way a one-line question is; images, code and
  // tables keep their normal weight and are sized to fit the card.
  function cardBodyHtml(markdown) {
    // breaks: ChatGPT shows a user message as typed, so a single newline is a
    // real line break and must survive as <br>, not collapse into a space.
    let html = String(markedLib.parse(String(markdown || "").trim(), { breaks: true }) || "").trim();
    html = html.replace(/<p>([\s\S]*?)<\/p>/g, '<p style="margin:0 0 8px"><strong>$1</strong></p>');
    html = html.replace(/<img /g, '<img style="max-width:100%;height:auto;border-radius:8px" ');
    html = html.replace(/<pre>/g, '<pre style="margin:0 0 8px;white-space:pre-wrap">');
    html = html.replace(/<table>/g, '<table style="border-collapse:collapse;margin:0 0 8px">');
    // The card must stay one HTML block, so no newline may survive. Inside a
    // <pre> the reference still renders as a line break; elsewhere it is just
    // whitespace.
    return html.replace(/\r?\n/g, "&#10;");
  }

  // Splits a message for a Markdown cell, which holds one line of inline
  // content: `prose` are the plain sentences, `rest` everything that stays
  // below the card, and `inline` the positions in `rest` that a cell could
  // still hold -- images and attachment lines -- should there be no prose.
  function splitProse(content) {
    const prose = [];
    const rest = [];
    const inline = [];
    let fence = false;
    for (const raw of String(content).split(/\r?\n/)) {
      const line = raw.trim();
      if (/^(```|~~~)/.test(line)) { fence = !fence; rest.push(raw); continue; }
      if (fence || !line || /^\|/.test(line)) { rest.push(raw); continue; }
      if (/!\[/.test(line) || isAttachmentLine(line)) { inline.push(rest.length); rest.push(line); continue; }
      prose.push(line);
    }
    return { prose, rest, inline };
  }

  // A Markdown table row ends at the physical newline. Keep a multi-line
  // question in one cell by using the portable inline line-break element;
  // otherwise every pasted line is interpreted as a new table/card.
  const proseCard = (lines) => {
    const content = lines.map((line) => `**${cellPipes(line)}**`).join("<br>");
    return [`| ${content} |`, "| :--- |", ""];
  };
  // A promoted line carries its own emphasis already, so it is not bolded.
  const inlineCard = (line) => [`| ${cellPipes(line)} |`, "| :--- |", ""];
  // Nothing the cell can hold: an empty card still marks the message as a
  // question, with its blocks following underneath.
  const EMPTY_CARD = ["| &nbsp; |", "| :--- |", ""];

  function questionCard(text, allowHtml) {
    const content = String(text || "").trim();
    if (!content) return null;
    if (allowHtml) {
      return [
        `<table style="${CARD_TABLE_STYLE}"><tbody><tr><td style="${CARD_CELL_STYLE}">${cardBodyHtml(content)}</td></tr></tbody></table>`,
        "",
      ];
    }
    // A question typed on several lines remains one card. The rest of the
    // message -- images, attachments, code, pasted tables -- follows it.
    const { prose, rest, inline } = splitProse(content);
    const cards = [];
    let below = rest;
    if (prose.length) {
      cards.push(...proseCard(prose));
    } else if (inline.length) {
      // No sentence at all -- an image dropped on its own, an attachment sent
      // without a comment: what a cell can hold moves into the card.
      for (const i of inline) cards.push(...inlineCard(rest[i]));
      below = rest.filter((_, i) => !inline.includes(i));
    } else {
      cards.push(...EMPTY_CARD);
    }
    const tail = below.join("\n").trim();
    return [...cards, ...(tail ? [tail, ""] : [])];
  }

  function toMarkdown(conv, turns, options = {}) {
    const allowHtml = options.mdHtml !== false;
    const lines = [`# ${conv.title || "Untitled"}`, ""];
    // The card itself already separates a user question from the surrounding
    // conversation. A rule is useful only between the end of a thinking chain
    // and the definitive answer that follows it.
    let previousRole = null;
    turns.forEach((t) => {
      const content = t.md.join("\n\n");
      const card = t.role === "user" ? questionCard(content, allowHtml) : null;
      if (card) {
        lines.push(...card);
      } else {
        if (t.role === "assistant" && previousRole === "thinking") lines.push("---", "");
        // No role label at all: the card marks the question, and everything
        // else -- answers and thinking summaries -- is plain text.
        lines.push(content, "");
      }
      previousRole = t.role;
    });
    return lines.join("\n").trimEnd() + "\n";
  }

  function toHtml(conv, turns) {
    const title = conv.title || "Untitled";
    const body = turns
      .map((t) => t.role === "user"
        ? `<section class="turn user" aria-label="${ROLE_LABELS.user}"><div class="turn-label">${ROLE_LABELS.user}</div><div class="bubble">${t.html.join("\n")}</div></section>`
        : t.role === "thinking"
          ? `<section class="turn thinking" aria-label="${ROLE_LABELS.thinking}"><div class="turn-label">${ROLE_LABELS.thinking}</div><div class="body">${t.html.join("\n")}</div></section>`
          : `<section class="turn assistant" aria-label="${ROLE_LABELS.assistant}"><div class="turn-label">${ROLE_LABELS.assistant}</div><div class="body">${t.html.join("\n")}</div></section>`)
      .join("\n");
    return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>${PAGE_CSS}</style>
</head>
<body>
<main class="page">
<header class="conv"><h1>${esc(title)}</h1></header>
${body}
<footer>Exported with ChatGPT Markdown Export.</footer>
</main>
</body>
</html>
`;
  }

  function indexHtml(entries) {
    const rows = entries
      .map((e) => {
        const meta = [e.project ? `Project: ${e.project}` : "", e.archived ? "Archived" : "", e.shared ? "Shared" : "", e.messages != null ? `${e.messages} messages` : "", e.size ? e.size : ""].filter(Boolean).join(" · ");
        const search = `${e.title || ""} ${e.project || ""} ${e.date || ""} ${meta} ${e.search || ""}`.toLowerCase();
        return `<li data-search="${esc(search)}"><div><a href="${esc(e.href)}">${esc(e.title)}</a>${meta ? `<small>${esc(meta)}</small>` : ""}</div><span>${esc(e.date)}</span></li>`;
      })
      .join("\n");
    return `<!doctype html>
<html lang="fr">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Export ChatGPT</title><style>${PAGE_CSS}
.search{width:100%;padding:10px 12px;margin:0 0 18px;border:1px solid var(--line);border-radius:10px;background:var(--card);color:var(--ink);font:inherit}.index li>div{min-width:0}.index small{display:block;color:var(--muted);font-size:12px;margin-top:2px}
</style></head>
<body><main class="page">
<header class="conv"><h1>ChatGPT Export</h1><p><span id="count">${entries.length}</span> conversation(s)</p></header>
<input id="q" class="search" type="search" placeholder="Search titles, projects, dates…" aria-label="Search">
<ul class="index" id="idx">${rows}</ul>
<script>const q=document.getElementById('q'), rows=[...document.querySelectorAll('#idx li')], count=document.getElementById('count');q.addEventListener('input',()=>{const x=q.value.trim().toLowerCase();let n=0;for(const r of rows){const show=!x||r.dataset.search.includes(x);r.hidden=!show;if(show)n++;}count.textContent=n;});<\/script>
</main></body></html>
`;
  }

  const PAGE_CSS = `
:root{--bg:#ffffff;--ink:#0d0d0d;--muted:#5d5d5d;--line:#e5e5e5;--chip:#f0f0f0;--chip-ink:#4a4a4a;--bubble:#e3ebf8;--bubble-ink:#0d0d0d;--link:#1f5fbf;--card:#f7f7f8;--pop:#ffffff;
--font:ui-sans-serif,-apple-system,system-ui,"Segoe UI",Helvetica,Arial,sans-serif}
@media (prefers-color-scheme:dark){:root{--bg:#000000;--ink:#ececec;--muted:#afafaf;--line:#303030;--chip:#2f2f2f;--chip-ink:#cdcdcd;--bubble:#1c3b73;--bubble-ink:#ffffff;--link:#8ab4f8;--card:#171717;--pop:#2a2a2a}}
*,*::before,*::after{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.75 var(--font);-webkit-font-smoothing:antialiased}
.page{max-width:768px;margin:0 auto;padding:32px 20px 80px}
header.conv{margin-bottom:40px}
header.conv h1{font-size:18px;font-weight:600;line-height:1.4;margin:0}
header.conv p{margin:2px 0 0;color:var(--muted);font-size:13px}
.turn{margin-bottom:40px}
.turn-label{margin-bottom:10px;color:var(--muted);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}
.turn.assistant{border-left:3px solid var(--accent);padding-left:20px}
.turn.user{display:flex;justify-content:flex-end}
.turn.user .turn-label{align-self:flex-start;margin:10px 14px 0 0}
.bubble{background:var(--bubble);color:var(--bubble-ink);padding:10px 20px;border-radius:24px;max-width:70%;line-height:1.6}
.bubble .plain{white-space:pre-wrap;overflow-wrap:anywhere}
.bubble figure{margin:6px 0}
.bubble img{max-width:100%;border-radius:16px}
.thought{color:var(--muted);font-size:15px;margin-bottom:12px}.thinking{border-left:3px solid var(--accent);padding-left:16px;opacity:.9}
.body{overflow-wrap:break-word}
.body p{margin:0 0 16px}
.body strong{font-weight:600}
.body h1{font-size:26px}.body h2{font-size:22px}.body h3{font-size:20px}.body h4{font-size:17px}
.body h1,.body h2,.body h3,.body h4{font-weight:600;line-height:1.35;margin:28px 0 10px}
.body a{color:var(--link);text-decoration:none}
.body ul,.body ol{margin:0 0 16px;padding-left:26px}
.body li{margin:4px 0}
.body hr{border:0;border-top:1px solid var(--line);margin:28px 0}
.body pre{background:var(--card);border-radius:12px;padding:14px 16px;overflow-x:auto;font-size:14px;line-height:1.55}
.body code{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:.875em}
.body :not(pre)>code{background:var(--chip);padding:2px 5px;border-radius:5px}
.body blockquote{margin:0 0 16px;padding-left:16px;border-left:3px solid var(--line);color:var(--muted)}
.table-wrap{overflow-x:auto;margin:4px 0 20px}
table{border-collapse:collapse;width:100%;font-size:15px;line-height:1.7}
th,td{padding:10px 20px 10px 0;text-align:left;vertical-align:top;border-bottom:1px solid var(--line)}
th:last-child,td:last-child{padding-right:0}
th{font-weight:600}
tbody tr:last-child td{border-bottom:0}
th[align=right],td[align=right]{text-align:right;white-space:nowrap}
th[align=center],td[align=center]{text-align:center}
.cite{position:relative;display:inline-block;vertical-align:1px}
.cite>a{display:inline-flex;align-items:center;gap:4px;font-size:12px;line-height:1;background:var(--chip);color:var(--chip-ink);padding:5px 9px;border-radius:999px;white-space:nowrap;max-width:190px;overflow:hidden;text-overflow:ellipsis}
.cite>a:hover{filter:brightness(1.15)}
.cite .more{opacity:.7}
.cite .pop{display:none;position:absolute;left:0;top:100%;z-index:5;min-width:260px;max-width:360px;background:var(--pop);border:1px solid var(--line);border-radius:12px;padding:6px;box-shadow:0 8px 24px rgba(0,0,0,.25)}
.cite:hover .pop,.cite:focus-within .pop{display:block}
.pop a{display:block;padding:6px 8px;border-radius:8px;font-size:13px;line-height:1.35;color:var(--ink)}
.pop a:hover{background:var(--chip)}
.pop small{display:block;color:var(--muted);font-size:11.5px}
.gallery{display:flex;gap:4px;overflow-x:auto;margin:4px 0 20px;scrollbar-width:thin}
.gallery a{flex:0 0 calc((100% - 8px) / 3)}
.gallery img{display:block;width:100%;height:222px;border-radius:12px;object-fit:cover;object-position:top}
.carousel{display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;margin:8px 0 24px;padding-bottom:6px;scrollbar-width:thin}
.product{flex:0 0 300px;scroll-snap-align:start;display:flex;flex-direction:column;color:inherit;text-decoration:none}
.body a.product{color:inherit}
.product img,.product .noimg{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:16px;background:var(--card);display:block;margin-bottom:10px}
.product strong{font-size:16px;font-weight:500;line-height:1.4}
.product .meta{color:var(--muted);font-size:15px;line-height:1.5}
figure.asset{margin:0 0 16px}
figure.asset img{max-width:min(100%,600px);border-radius:24px;display:block}
.attachment{font-size:14px;color:var(--muted)}
.filecite{font-size:12px;background:var(--chip);color:var(--chip-ink);padding:3px 7px;border-radius:999px;text-decoration:none}
.index{list-style:none;padding:0;margin:0}
.index li{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid var(--line)}
.index a{color:var(--link);text-decoration:none}
.index span{color:var(--muted);font-size:14px;white-space:nowrap}
footer{margin-top:56px;padding-top:16px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}
footer code{overflow-wrap:anywhere}
@media (max-width:560px){.bubble{max-width:90%}.gallery a{flex-basis:45%}.gallery img{height:160px}.product{flex-basis:240px}}
`;

  function safeName(conv) {
    const d = toDate(conv.create_time);
    const date = d ? d.toISOString().slice(0, 10) : "sans-date";
    const slug =
      (conv.title || "sans-titre")
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/[^a-zA-Z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .toLowerCase()
        .slice(0, 60) || "sans-titre";
    return `${date}_${slug}`;
  }

  // Image context for a conversation: each distinct image receives a unique marker.
  function createContext() {
    const images = [];
    const files = [];
    const byKey = new Map();
    const fileKey = new Map();
    return {
      images, files,
      image(candidates, isAsset) {
        const key = candidates[0];
        if (byKey.has(key)) return byKey.get(key).ph;
        const entry = { ph: `CGXIMG${images.length}Z`, candidates, isAsset };
        images.push(entry); byKey.set(key, entry); return entry.ph;
      },
      file(candidates, name, meta = {}) {
        const key = `${candidates[0] || ""}|${meta.messageId || ""}`;
        if (fileKey.has(key)) return fileKey.get(key).ph;
        const entry = { ph: `CGXFILE${files.length}Z`, candidates, name: name || `file-${files.length + 1}`, ...meta };
        files.push(entry); fileKey.set(key, entry); return entry.ph;
      },
    };
  }

  globalThis.CGX = { createContext, buildTurns, branchLeaves, toMarkdown, toHtml, indexHtml, safeName, formatDate, isArchiveSafeUrl, sanitizeMarkdownLinks };
})();
